 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; pub fn process_dependencies_for_output_crate (original_deps : & Table , global_config : & SplitDeclsConfig , output_dir : & Path , project_root : & Path , verbose : bool ,) -> anyhow :: Result < Table > { let mut new_deps = Table :: new () ; for (dep_name , dep_value) in original_deps . iter () { if let Some (dep_table) = dep_value . as_table () { let mut processed_dep_table = dep_table . clone () ; if dep_table . contains_key ("workspace") && dep_table ["workspace"] . as_bool () . unwrap_or (false) { if let Some (resolved_dep_info) = global_config . workspace_dependencies . get (dep_name) { if let Some (resolved_path_str) = resolved_dep_info . get ("path") . and_then (| v | v . as_str ()) { let absolute_resolved_path = project_root . join (resolved_path_str) ; let relative_path = path_diff (output_dir , & absolute_resolved_path) . context (format ! ("Failed to calculate relative path for workspace dep '{}'" , dep_name)) ? ; processed_dep_table . insert ("path" . to_string () , Value :: String (relative_path . display () . to_string ())) ; processed_dep_table . remove ("workspace") ; processed_dep_table . remove ("version") ; } else if let Some (resolved_version_str) = resolved_dep_info . get ("version") . and_then (| v | v . as_str ()) { processed_dep_table . insert ("version" . to_string () , Value :: String (resolved_version_str . to_string ())) ; processed_dep_table . remove ("workspace") ; } else { if verbose { println ! ("Warning: No path or version found for workspace dependency '{}' in global_config. Keeping original." , dep_name) ; } } } else { if verbose { println ! ("Warning: Workspace dependency '{}' not found in global_config. Keeping original." , dep_name) ; } } } else if let Some (original_path_value) = dep_table . get ("path") { if let Some (original_path_str) = original_path_value . as_str () { let absolute_original_path = project_root . join (original_path_str) ; let relative_path = path_diff (output_dir , & absolute_original_path) . context (format ! ("Failed to calculate relative path for path dep '{}'" , dep_name)) ? ; processed_dep_table . insert ("path" . to_string () , Value :: String (relative_path . display () . to_string ())) ; } } new_deps . insert (dep_name . clone () , Value :: Table (processed_dep_table)) ; } else { new_deps . insert (dep_name . clone () , dep_value . clone ()) ; } } Ok (new_deps) }